from __future__ import annotations

import json
import time
from contextlib import asynccontextmanager
from pathlib import Path

from fastapi import FastAPI, WebSocket, WebSocketDisconnect
from fastapi.responses import JSONResponse
from fastapi.staticfiles import StaticFiles

from ..app import AppContext

FRONTEND_DIR = Path(__file__).resolve().parent.parent.parent / "frontend"

LEADERBOARD_CACHE_TTL_S = 180.0
LEADERBOARD_DAYS = 90


def create_app(ctx: AppContext) -> FastAPI:
    leaderboard_cache: dict = {"ts": 0.0, "data": None}
    @asynccontextmanager
    async def lifespan(app: FastAPI):
        ctx.start()
        yield
        await ctx.stop()

    app = FastAPI(title="tradebot", lifespan=lifespan)

    # All routes below are async def, even where nothing is awaited: the
    # single sqlite3.Connection (Database.conn) is otherwise only ever
    # touched from the asyncio event loop thread (hub polling, signal
    # engine, bot tick loops). A sync `def` route gets dispatched by
    # FastAPI to a worker threadpool, which races that connection from a
    # second OS thread and intermittently raises
    # "sqlite3.InterfaceError: bad parameter or other API misuse". Keeping
    # every route as async def keeps all DB access on one thread.
    @app.get("/api/bots")
    async def list_bots():
        out = []
        for bot in ctx.bots.values():
            wallet = ctx.db.get_wallet(bot.wallet_id)
            positions = ctx.db.positions(bot.wallet_id, status="open")
            positions_value = sum(
                (p["current_price"] or p["avg_entry_price"]) * p["qty"] for p in positions
            )
            out.append(
                {
                    "bot_id": bot.bot_id,
                    "description": bot.strategy.description,
                    "paused": bot.paused(),
                    "wallet": wallet,
                    "equity": (wallet["balance"] + positions_value) if wallet else None,
                    "open_positions": len(positions),
                    "params": bot.ctx.params,
                }
            )
        return out

    @app.post("/api/bots/{bot_id}/pause")
    async def pause_bot(bot_id: str):
        bot = ctx.bots.get(bot_id)
        if bot is None:
            return JSONResponse({"error": "unknown bot"}, status_code=404)
        bot.pause()
        return {"ok": True}

    @app.post("/api/bots/{bot_id}/resume")
    async def resume_bot(bot_id: str):
        bot = ctx.bots.get(bot_id)
        if bot is None:
            return JSONResponse({"error": "unknown bot"}, status_code=404)
        bot.resume()
        return {"ok": True}

    @app.get("/api/positions")
    async def positions(bot_id: str | None = None, status: str = "open"):
        if bot_id:
            bot = ctx.bots.get(bot_id)
            if bot is None:
                return JSONResponse({"error": "unknown bot"}, status_code=404)
            return ctx.db.positions(bot.wallet_id, status=status)
        out = []
        for bot in ctx.bots.values():
            out.extend(ctx.db.positions(bot.wallet_id, status=status))
        return out

    @app.get("/api/signals")
    async def signals(symbol: str | None = None, hours: float = 24.0):
        return ctx.db.recent_signals(symbol, hours=hours)

    @app.get("/api/equity/{bot_id}")
    async def equity(bot_id: str, hours: float = 24.0):
        bot = ctx.bots.get(bot_id)
        if bot is None:
            return JSONResponse({"error": "unknown bot"}, status_code=404)
        return ctx.db.equity_history(bot.wallet_id, hours=hours)

    @app.get("/api/quotes")
    async def quotes():
        out = {}
        for symbol in ctx.cfg.symbols:
            q = ctx.hub.get_quote(symbol)
            out[symbol] = {"price": q.price, "ts": q.ts} if q else None
        return out

    @app.get("/api/candles")
    async def candles(symbol: str = "BTCUSDT", interval: str = "1h", limit: int = 200):
        from ..data.binance_client import INTERVAL_SECONDS
        from ..signals.market_structure import support_resistance_levels
        from ..signals.ohlcv import bucket_history

        interval_s = INTERVAL_SECONDS.get(interval, 3600)
        rows = ctx.db.ohlcv_history(symbol, interval_s)
        if rows:
            bars = [
                {"ts": r["ts"], "open": r["open"], "high": r["high"], "low": r["low"], "close": r["close"], "volume": r["volume"]}
                for r in rows
            ]
        else:
            history = ctx.db.snapshot_history(symbol, hours=24 * 30)
            bars = bucket_history(history, interval_s, min_bars=1) or []
        bars = bars[-limit:]

        levels = support_resistance_levels(bars) if bars else []

        since = bars[0]["ts"] if bars else 0.0
        markers = []
        for sig in ctx.db.recent_signals(symbol, hours=24 * 400):
            if sig["rule"] != "candlestick_pattern" or sig["ts"] < since:
                continue
            details = sig["details_json"]
            if isinstance(details, str):
                details = json.loads(details)
            markers.append({"ts": sig["ts"], "direction": sig["direction"], "pattern": (details or {}).get("pattern")})

        return {"symbol": symbol, "interval_s": interval_s, "bars": bars, "levels": levels, "markers": markers}

    @app.get("/api/backtest")
    async def backtest(strategy: str, symbol: str = "BTCUSDT", interval: str = "1h", days: int = 180):
        from ..backtest.engine import run_backtest
        from ..backtest.run import STRATEGIES

        if strategy not in STRATEGIES:
            return JSONResponse({"error": f"unknown strategy: {strategy}"}, status_code=400)
        try:
            result = await run_backtest(STRATEGIES[strategy], symbol, interval, days)
        except (RuntimeError, ValueError) as exc:
            return JSONResponse({"error": str(exc)}, status_code=400)
        return result.__dict__

    @app.get("/api/trades")
    async def trades(bot_id: str, limit: int = 50):
        bot = ctx.bots.get(bot_id)
        if bot is None:
            return JSONResponse({"error": "unknown bot"}, status_code=404)
        return ctx.db.closed_trades(bot.wallet_id, limit=limit)

    @app.get("/api/leaderboard")
    async def leaderboard(force: bool = False):
        from ..backtest.engine import run_backtest
        from ..backtest.run import STRATEGIES

        now = time.time()
        if not force and leaderboard_cache["data"] is not None:
            if now - leaderboard_cache["ts"] < LEADERBOARD_CACHE_TTL_S:
                return leaderboard_cache["data"]

        symbol = ctx.cfg.symbols[0]
        results = []
        for name, strategy_cls in STRATEGIES.items():
            try:
                result = await run_backtest(strategy_cls, symbol, "1h", LEADERBOARD_DAYS)
                summary = result.__dict__.copy()
                summary.pop("equity_curve", None)  # leaderboard is a summary card, not a chart
                results.append(summary)
            except (RuntimeError, ValueError) as exc:
                results.append({"strategy": name, "symbol": symbol, "error": str(exc)})

        leaderboard_cache["ts"] = now
        leaderboard_cache["data"] = results
        return results

    @app.get("/api/ml/explain")
    async def ml_explain():
        """Per-symbol view of what the ML model is 'watching': its latest
        up/flat/down class probabilities plus the features it weights most.
        Reuses the models already loaded on the signal engine's ML rule --
        no re-loading, no extra Binance calls."""
        from ..ml.predictor import explain_from_rows

        predictors: dict = {}
        for rule in ctx.signals.rules:
            if hasattr(rule, "predictors"):
                predictors = rule.predictors
                break

        out = []
        for symbol in ctx.cfg.symbols:
            predictor = predictors.get(symbol)
            enabled = bool(predictor is not None and predictor.enabled)
            entry: dict = {"symbol": symbol, "enabled": enabled, "explain": None}
            if enabled:
                rows = ctx.db.ohlcv_history(symbol, 3600)
                entry["explain"] = explain_from_rows(predictor, rows)
            out.append(entry)
        return out

    @app.websocket("/ws")
    async def ws_endpoint(ws: WebSocket):
        await ctx.events.connect(ws)
        try:
            while True:
                await ws.receive_text()
        except WebSocketDisconnect:
            ctx.events.disconnect(ws)

    if FRONTEND_DIR.exists():
        app.mount("/", StaticFiles(directory=str(FRONTEND_DIR), html=True), name="frontend")

    return app

