from __future__ import annotations

from ..models import Quote


class BacktestHub:
    """Same read interface as DataHub (get_quote/fetch_quote), but serves a
    single replayed historical bar instead of live Binance data. Strategies
    and rules see the exact same API they'd see live -- no backtest-specific
    branch anywhere in strategy/rule code."""

    def __init__(self):
        self.current: Quote | None = None

    def set_bar(self, symbol: str, price: float, ts: float) -> None:
        self.current = Quote(symbol=symbol, price=price, ts=ts)

    def get_quote(self, symbol: str) -> Quote | None:
        if self.current is not None and self.current.symbol == symbol:
            return self.current
        return None

    async def fetch_quote(self, symbol: str) -> Quote | None:
        return self.get_quote(symbol)

