from __future__ import annotations

import logging
from abc import ABC, abstractmethod
from pathlib import Path
from typing import TYPE_CHECKING

from ..config import Settings

if TYPE_CHECKING:
    import pandas as pd

logger = logging.getLogger(__name__)


class MlPredictor(ABC):
    enabled: bool = False

    @abstractmethod
    def predict(self, ohlcv: "pd.DataFrame") -> float | None:
        """Return a -1..+1 'intelligent indicator' score, or None if it
        can't predict yet (e.g. not enough history for the features)."""

    def explain(self, ohlcv: "pd.DataFrame") -> dict | None:
        """Return a dashboard-friendly breakdown of the latest prediction:
        the up/flat/down class probabilities, the -1..+1 score, and the
        features the model weights most. None if it can't predict yet."""
        return None


class NullMlPredictor(MlPredictor):
    enabled = False

    def predict(self, ohlcv: "pd.DataFrame") -> float | None:
        return None


class SklearnMlPredictor(MlPredictor):
    def __init__(self, model_path: Path):
        import joblib

        from .features import FEATURE_COLUMNS, build_feature_frame

        self._build_feature_frame = build_feature_frame
        self._feature_columns = list(FEATURE_COLUMNS)
        self.model = joblib.load(model_path)
        self.enabled = True

    def predict(self, ohlcv: "pd.DataFrame") -> float | None:
        try:
            df = self._build_feature_frame(ohlcv)
            row = df.iloc[[-1]][self._feature_columns]
            if bool(row.isna().any(axis=1).iloc[0]):
                return None
            proba = self.model.predict_proba(row)[0]
            classes = list(self.model.classes_)
            p_up = float(proba[classes.index(1)]) if 1 in classes else 0.0
            p_down = float(proba[classes.index(-1)]) if -1 in classes else 0.0
            return p_up - p_down
        except Exception:
            logger.exception("ml predictor failed, returning no signal")
            return None

    def explain(self, ohlcv: "pd.DataFrame") -> dict | None:
        try:
            df = self._build_feature_frame(ohlcv)
            row = df.iloc[[-1]][self._feature_columns]
            if bool(row.isna().any(axis=1).iloc[0]):
                return None
            proba = self.model.predict_proba(row)[0]
            classes = list(self.model.classes_)

            def pc(c: int) -> float:
                return float(proba[classes.index(c)]) if c in classes else 0.0

            importances = getattr(self.model, "feature_importances_", None)
            top_features: list[dict] = []
            if importances is not None:
                ranked = sorted(
                    zip(self._feature_columns, (float(x) for x in importances)),
                    key=lambda kv: kv[1],
                    reverse=True,
                )
                top_features = [{"name": n, "weight": round(w, 4)} for n, w in ranked[:8]]

            p_up, p_flat, p_down = pc(1), pc(0), pc(-1)
            return {
                "score": round(p_up - p_down, 3),
                "proba": {"up": round(p_up, 3), "flat": round(p_flat, 3), "down": round(p_down, 3)},
                "top_features": top_features,
            }
        except Exception:
            logger.exception("ml explain failed")
            return None


def build_ml_predictor_for_symbol(cfg: Settings, symbol: str) -> MlPredictor:
    """One model per symbol -- a model trained on BTCUSDT doesn't transfer
    reliably to other symbols' price/volatility scale (confirmed empirically:
    applying a BTC-only model to ETHUSDT/SOLUSDT produced suspiciously
    overconfident, miscalibrated scores). Falls back to NullMlPredictor if
    ML_ENABLED is off or this specific symbol has no trained model yet --
    run `python -m tradebot.ml.train --symbol {symbol}`."""
    if not cfg.ml_enabled:
        return NullMlPredictor()
    model_path = Path(cfg.ml_models_dir) / f"{symbol}.joblib"
    if not model_path.exists():
        logger.info(
            "ML_ENABLED but no model file for %s at %s -- run "
            "`python -m tradebot.ml.train --symbol %s` first",
            symbol, model_path, symbol,
        )
        return NullMlPredictor()
    try:
        return SklearnMlPredictor(model_path)
    except ImportError:
        logger.warning(
            "ML_ENABLED but scikit-learn/pandas/pandas-ta not installed -- "
            "pip install -r requirements-ml.txt"
        )
        return NullMlPredictor()


def build_ml_predictors(cfg: Settings) -> dict[str, MlPredictor]:
    return {symbol: build_ml_predictor_for_symbol(cfg, symbol) for symbol in cfg.symbols}


def explain_from_rows(predictor: MlPredictor, rows: list[dict]) -> dict | None:
    """Adapter for the API layer: turn raw ohlcv_history rows into the frame
    the predictor wants and return its explanation. Pandas is imported here
    (not at module top) so the always-on server never pulls the ML deps just
    to import this module."""
    if not getattr(predictor, "enabled", False) or not rows:
        return None
    import pandas as pd

    df = pd.DataFrame(rows)[["ts", "open", "high", "low", "close", "volume"]]
    return predictor.explain(df)

