"""Candlestick pattern detection, straight from The Candlestick Trading
Bible's geometric definitions (bearish/bullish engulfing p.16-19, doji
p.20-27, morning/evening star p.28-33, hammer/shooting star p.34-39,
harami p.40-42, tweezers p.43-45).

Every function takes the full list of OHLCV bar dicts (oldest-first) and
looks only at the trailing 1-3 bars it needs. No pandas -- pure arithmetic,
so this works even without requirements-ml.txt installed.
"""
from __future__ import annotations

from typing import Callable

Bar = dict


def _body(bar: Bar) -> float:
    return abs(bar["close"] - bar["open"])


def _range(bar: Bar) -> float:
    return bar["high"] - bar["low"]


def _body_lo(bar: Bar) -> float:
    return min(bar["open"], bar["close"])


def _body_hi(bar: Bar) -> float:
    return max(bar["open"], bar["close"])


def _upper_shadow(bar: Bar) -> float:
    return bar["high"] - _body_hi(bar)


def _lower_shadow(bar: Bar) -> float:
    return _body_lo(bar) - bar["low"]


def _is_bullish(bar: Bar) -> bool:
    return bar["close"] > bar["open"]


def _is_bearish(bar: Bar) -> bool:
    return bar["close"] < bar["open"]


def _engulfs(outer: Bar, inner: Bar) -> bool:
    return _body_lo(outer) <= _body_lo(inner) and _body_hi(outer) >= _body_hi(inner)


def bullish_engulfing(bars: list[Bar]) -> bool:
    if len(bars) < 2:
        return False
    a, b = bars[-2], bars[-1]
    return _is_bearish(a) and _is_bullish(b) and _engulfs(b, a)


def bearish_engulfing(bars: list[Bar]) -> bool:
    if len(bars) < 2:
        return False
    a, b = bars[-2], bars[-1]
    return _is_bullish(a) and _is_bearish(b) and _engulfs(b, a)


def doji(bars: list[Bar], body_ratio: float = 0.05) -> bool:
    if not bars:
        return False
    bar = bars[-1]
    r = _range(bar)
    return r > 0 and _body(bar) <= body_ratio * r


def dragonfly_doji(bars: list[Bar]) -> bool:
    if not bars:
        return False
    bar = bars[-1]
    r = _range(bar)
    if r <= 0 or not doji(bars):
        return False
    return _upper_shadow(bar) <= 0.1 * r and _lower_shadow(bar) >= 0.6 * r


def gravestone_doji(bars: list[Bar]) -> bool:
    if not bars:
        return False
    bar = bars[-1]
    r = _range(bar)
    if r <= 0 or not doji(bars):
        return False
    return _lower_shadow(bar) <= 0.1 * r and _upper_shadow(bar) >= 0.6 * r


def hammer(bars: list[Bar]) -> bool:
    if not bars:
        return False
    bar = bars[-1]
    r = _range(bar)
    if r <= 0:
        return False
    b = _body(bar)
    return (
        b <= 0.35 * r
        and _lower_shadow(bar) >= 2 * b
        and _lower_shadow(bar) >= 0.4 * r
        and _upper_shadow(bar) <= 0.15 * r
    )


def shooting_star(bars: list[Bar]) -> bool:
    if not bars:
        return False
    bar = bars[-1]
    r = _range(bar)
    if r <= 0:
        return False
    b = _body(bar)
    return (
        b <= 0.35 * r
        and _upper_shadow(bar) >= 2 * b
        and _upper_shadow(bar) >= 0.4 * r
        and _lower_shadow(bar) <= 0.15 * r
    )


def morning_star(bars: list[Bar]) -> bool:
    if len(bars) < 3:
        return False
    c1, c2, c3 = bars[-3], bars[-2], bars[-1]
    r1 = _range(c1)
    if r1 <= 0:
        return False
    midpoint = (c1["open"] + c1["close"]) / 2
    return (
        _is_bearish(c1)
        and _body(c1) >= 0.5 * r1
        and _body(c2) <= 0.3 * r1
        and _is_bullish(c3)
        and c3["close"] > midpoint
    )


def evening_star(bars: list[Bar]) -> bool:
    if len(bars) < 3:
        return False
    c1, c2, c3 = bars[-3], bars[-2], bars[-1]
    r1 = _range(c1)
    if r1 <= 0:
        return False
    midpoint = (c1["open"] + c1["close"]) / 2
    return (
        _is_bullish(c1)
        and _body(c1) >= 0.5 * r1
        and _body(c2) <= 0.3 * r1
        and _is_bearish(c3)
        and c3["close"] < midpoint
    )


def bullish_harami(bars: list[Bar]) -> bool:
    if len(bars) < 2:
        return False
    mother, baby = bars[-2], bars[-1]
    return _is_bearish(mother) and _body(baby) < _body(mother) and _engulfs(mother, baby)


def bearish_harami(bars: list[Bar]) -> bool:
    if len(bars) < 2:
        return False
    mother, baby = bars[-2], bars[-1]
    return _is_bullish(mother) and _body(baby) < _body(mother) and _engulfs(mother, baby)


def tweezers_top(bars: list[Bar]) -> bool:
    if len(bars) < 2:
        return False
    a, b = bars[-2], bars[-1]
    avg_range = (_range(a) + _range(b)) / 2
    if avg_range <= 0:
        return False
    return _is_bullish(a) and _is_bearish(b) and abs(a["high"] - b["high"]) <= 0.1 * avg_range


def tweezers_bottom(bars: list[Bar]) -> bool:
    if len(bars) < 2:
        return False
    a, b = bars[-2], bars[-1]
    avg_range = (_range(a) + _range(b)) / 2
    if avg_range <= 0:
        return False
    return _is_bearish(a) and _is_bullish(b) and abs(a["low"] - b["low"]) <= 0.1 * avg_range


# name -> (detector, direction). direction is the pattern's inherent bias;
# "doji" has no inherent direction -- context (trend) decides, see
# candlestick_rule.py.
PATTERNS: list[tuple[str, Callable[[list[Bar]], bool], str | None]] = [
    ("bullish_engulfing", bullish_engulfing, "bullish"),
    ("bearish_engulfing", bearish_engulfing, "bearish"),
    ("dragonfly_doji", dragonfly_doji, "bullish"),
    ("gravestone_doji", gravestone_doji, "bearish"),
    ("morning_star", morning_star, "bullish"),
    ("evening_star", evening_star, "bearish"),
    ("hammer", hammer, "bullish"),
    ("shooting_star", shooting_star, "bearish"),
    ("bullish_harami", bullish_harami, "bullish"),
    ("bearish_harami", bearish_harami, "bearish"),
    ("tweezers_bottom", tweezers_bottom, "bullish"),
    ("tweezers_top", tweezers_top, "bearish"),
    ("doji", doji, None),
]


def detect_patterns(bars: list[Bar]) -> list[tuple[str, str | None]]:
    """Return every pattern matching the current bar window, most specific
    first (so e.g. dragonfly_doji is reported instead of/alongside plain
    doji when both match)."""
    hits = []
    for name, fn, direction in PATTERNS:
        if fn(bars):
            hits.append((name, direction))
    return hits

