"""Fibonacci retracement as a confluence factor -- p.96-99: 'I use the 61%
and 50% Fibonacci retracement to find the most powerful areas in the
market.' Used alongside trend + the 21-MA in the pin-bar-with-the-trend
strategy (p.98's 4-factor confluence example).
"""
from __future__ import annotations

RATIOS = (0.5, 0.618)


def retracement_levels(swing_low: float, swing_high: float) -> dict[str, dict[str, float]]:
    """Direction-agnostic: returns both interpretations of the swing since
    (swing_low, swing_high) alone doesn't say which came first.

    - "from_high": retracement levels measured pulling back DOWN from the
      high -- use these after an up-move (uptrend pullback, buy setup).
    - "from_low": retracement levels measured pulling back UP from the
      low -- use these after a down-move (downtrend pullback, sell setup).
    """
    span = swing_high - swing_low
    from_high = {f"{r:.3f}": swing_high - span * r for r in RATIOS}
    from_low = {f"{r:.3f}": swing_low + span * r for r in RATIOS}
    return {"from_high": from_high, "from_low": from_low}


def is_near_fib_level(price: float, levels: dict[str, float], tolerance_pct: float = 0.015) -> bool:
    if not levels or price <= 0:
        return False
    return any(abs(price - level) / price <= tolerance_pct for level in levels.values())
